(function(){
  'use strict';
  const engine=globalThis.WorldforgeBattle;if(!engine||typeof document==='undefined')return;
  const q=selector=>document.querySelector(selector);let state=null,selectedAttacker='';
  function cardNode(card,options={}){const article=document.createElement('article');article.className=`battle-card ${card.type}`;if(options.selected)article.classList.add('selected');const keywords=engine.keywordNames(card);article.innerHTML=`<div class="battle-card-cost">${card.cost}</div><strong>${card.name}</strong><small>${card.type==='minion'?`${card.attack} / ${card.health}`:'法术'}</small>${keywords.length?`<p>${keywords.join(' · ')}</p>`:''}`;if(options.action){const button=document.createElement('button');button.type='button';button.className='button compact';button.textContent=options.label||'选择';button.disabled=!!options.disabled;button.onclick=options.action;article.append(button)}return article}
  function heroNode(playerId){const owner=state.players[playerId],button=document.createElement('button');button.type='button';button.className='battle-hero';button.innerHTML=`<span>${owner.name}</span><strong>${owner.health} / ${owner.maxHealth}</strong><small>生命</small>`;const legal=selectedAttacker&&engine.legalAttackTargets(state,'player',selectedAttacker).some(item=>item.id===`${playerId}-hero`);button.disabled=!legal;button.onclick=()=>perform(()=>engine.attack(state,'player',selectedAttacker,`${playerId}-hero`));return button}
  function boardNode(playerId){const container=document.createElement('div');container.className='battle-board-row';const legalTargets=selectedAttacker?engine.legalAttackTargets(state,'player',selectedAttacker):[];state.players[playerId].board.forEach(card=>{const isOwn=playerId==='player',isLegal=legalTargets.some(item=>item.id===card.instanceId),canSelect=isOwn&&engine.canAttack(state,'player',card);container.append(cardNode(card,{selected:card.instanceId===selectedAttacker,label:isOwn?'攻击':isLegal?'作为目标':'不可选',disabled:isOwn?!canSelect:!isLegal,action:isOwn?()=>{selectedAttacker=selectedAttacker===card.instanceId?'':card.instanceId;render()}:isLegal?()=>perform(()=>engine.attack(state,'player',selectedAttacker,card.instanceId)):null}))});if(!container.children.length){const empty=document.createElement('p');empty.className='battle-empty';empty.textContent='暂无随从';container.append(empty)}return container}
  function perform(action){try{action();selectedAttacker='';render()}catch(error){q('#battleNotice').textContent=error.message}}
  function render(){if(!state)return;const player=state.players.player,enemy=state.players.opponent;q('#battleTurn').textContent=state.status==='finished'?'对战结束':`第 ${state.turn} 回合 · ${state.currentPlayer==='player'?'你的回合':'对手回合'}`;q('#battleMana').textContent=`${player.mana} / ${player.maxMana}`;q('#battleDeck').textContent=player.deck.length;q('#battleEnemyDeck').textContent=enemy.deck.length;q('#battleNotice').textContent=state.status==='finished'?(state.winner==='player'?'你获胜了。':state.winner==='draw'?'双方同时战败。':'规则对手获胜。'):(selectedAttacker?'请选择攻击目标。':'打出手牌，或选择己方随从发起攻击。');q('#battleEnemyHero').replaceChildren(heroNode('opponent'));q('#battlePlayerHero').replaceChildren(heroNode('player'));q('#battleEnemyBoard').replaceChildren(boardNode('opponent'));q('#battlePlayerBoard').replaceChildren(boardNode('player'));const hand=q('#battleHand');hand.replaceChildren();player.hand.forEach((card,index)=>hand.append(cardNode(card,{label:'打出',disabled:state.currentPlayer!=='player'||state.status!=='playing'||card.cost>player.mana||(card.type==='minion'&&player.board.length>=engine.RULES.maxBoard),action:()=>perform(()=>engine.playCard(state,'player',index))})));q('#battleEndTurn').disabled=state.currentPlayer!=='player'||state.status!=='playing';q('#battleLog').replaceChildren(...state.log.map(item=>{const row=document.createElement('li');row.textContent=`T${item.turn} · ${item.text}`;return row}))}
  function reset(){state=engine.createGame({seed:'worldforge-browser-battle-v1'});selectedAttacker='';render()}
  function endTurn(){perform(()=>{engine.endTurn(state,'player');if(state.status==='playing')engine.runRuleOpponent(state)})}
  q('#battleReset')?.addEventListener('click',reset);q('#battleEndTurn')?.addEventListener('click',endTurn);
  globalThis.WorldforgeBattleUI={refresh(){if(!state)reset();else render()},reset};
})();
